<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
defineProps<{ received: boolean }>();
const form = useForm({ name: '', email: '', subject: '', message: '' });
function submit() { form.post('/contact', { preserveScroll: true, onSuccess: () => form.reset() }); }
defineOptions({ name: 'ContactPage' });
</script>
<template><Head title="Обратная связь" /><section class="site-section reading-page"><p class="overline">СВЯЗЬ С ДРУГОЙ СТОРОНОЙ</p><h1>Расскажи о своём забеге.</h1><p>Нашли ошибку или хотите оставить отзыв? Сообщение будет сохранено в базе обращений. Уведомление по электронной почте не отправляется.</p><div v-if="received" role="status" class="notice">Обращение принято и сохранено. Спасибо за обратную связь.</div><form class="contact-form" @submit.prevent="submit"><template v-for="field in (['name', 'email', 'subject', 'message'] as const)" :key="field"><label :for="field">{{ { name: 'Имя', email: 'Email', subject: 'Тема', message: 'Сообщение' }[field] }}</label><textarea v-if="field === 'message'" :id="field" v-model="form[field]" required minlength="10" maxlength="5000" rows="6" :aria-invalid="!!form.errors[field]" :aria-describedby="form.errors[field] ? `${field}-error` : undefined" /><input v-else :id="field" v-model="form[field]" :type="field === 'email' ? 'email' : 'text'" required :maxlength="{ name: 100, email: 254, subject: 160 }[field]" :autocomplete="field === 'name' ? 'name' : field === 'email' ? 'email' : 'off'" :aria-invalid="!!form.errors[field]" :aria-describedby="form.errors[field] ? `${field}-error` : undefined" /><p v-if="form.errors[field]" :id="`${field}-error`" class="field-error">{{ form.errors[field] }}</p></template><p class="subtle">Не отправляйте пароли и платёжные данные. Сохранение обращения включает указанные имя, email и текст. <a href="/privacy">Сведения об обработке данных (проект)</a>.</p><button class="site-button" :disabled="form.processing">{{ form.processing ? 'Сохраняем…' : 'Отправить обращение →' }}</button></form></section></template>
